109		topLevelMemos := make([]*store.Memo, 0, benchmarkTopLevelMemoCount)
110		commentParentName := ""
111	
112		for i := 0; i < benchmarkTopLevelMemoCount; i++ {
113			visibility := store.Private
114			if i%4 == 0 {
115				visibility = store.Public
116			}
117			memo, err := stores.CreateMemo(ctx, &store.Memo{
118				UID:        fmt.Sprintf("memo-%06d", i),
119				CreatorID:  hostUser.ID,
120				Content:    benchmarkMemoContent(i),
121				Visibility: visibility,
122			})
123			if err != nil {
124				return "", err
125			}
126			topLevelMemos = append(topLevelMemos, memo)
127	
128			if i%3 == 0 {
129				if _, err := stores.CreateAttachment(ctx, &store.Attachment{
130					UID:       fmt.Sprintf("att-%06d", i),
131					CreatorID: hostUser.ID,
132					Filename:  fmt.Sprintf("memo-%06d.png", i),
133					Type:      "image/png",
134					Size:      2048,
135					MemoID:    &memo.ID,
136				}); err != nil {
137					return "", err
138				}
139			}
140	
141			if i%5 == 0 {
142				if _, err := stores.UpsertReaction(ctx, &store.Reaction{
143					CreatorID:    hostUser.ID,
144					ContentID:    "memos/" + memo.UID,
145					ReactionType: "thumbs-up",
146				}); err != nil {
147					return "", err
148				}
149			}
150		}
151	
152		for i, memo := range topLevelMemos {
153			if i+1 < len(topLevelMemos) && i%4 == 0 {
154				if _, err := stores.UpsertMemoRelation(ctx, &store.MemoRelation{
155					MemoID:        memo.ID,
156					RelatedMemoID: topLevelMemos[i+1].ID,
157					Type:          store.MemoRelationReference,
158				}); err != nil {
159					return "", err
160				}
161			}
162	
163			if i%6 == 0 {
164				commentMemo, err := stores.CreateMemo(ctx, &store.Memo{
165					UID:        fmt.Sprintf("comment-%06d", i),
166					CreatorID:  hostUser.ID,
167					Content:    fmt.Sprintf("Comment for memo %06d", i),
168					Visibility: store.Private,
169				})
170				if err != nil {
171					return "", err
172				}
173				if _, err := stores.UpsertMemoRelation(ctx, &store.MemoRelation{
174					MemoID:        commentMemo.ID,
175					RelatedMemoID: memo.ID,
176					Type:          store.MemoRelationComment,
177				}); err != nil {
178					return "", err
179				}
180				if commentParentName == "" {
181					commentParentName = "memos/" + memo.UID
182				}
183			}
